import { TriggerDefinition } from '../../TriggerDefinition'
import { NameValuePairsColumn, StringColumn, TableNameColumn } from '../../../db'

export const remoteTableQueryTrigger = TriggerDefinition({
    $id: '778cf3bf37232110aba6473174924b7c',
    name: 'Remote Table Query',
    type: 'remote_table_query',
    inputs: {
        u_table: TableNameColumn({
            label: 'Table',
            maxLength: 32,
            reference: 'sys_script_vtable',
            reference_display: 'Remote Table',
        }),
    },
    outputs: {
        table_name: TableNameColumn({
            label: 'Table Name',
        }),
        query_parameters: NameValuePairsColumn({
            label: 'Query Parameters',
        }),
        query_id: StringColumn({
            label: 'Query ID',
            isFullUTF8: true,
            maxLength: 255,
        }),
    },
})
